CREATE    VIEW [RegsBI].[vwSchemes]
AS
SELECT 
	sch.[cclregs_name],
	sch.[Modified_On],
	sch.[ModifiedByName],
	sch.[Created_On],
	sch.[CreatedByName],
	sch.[rics_prismschemereference],
	sch.[cclregs_regulatedschemetypeidName],
	sch.[cclregs_accountid],
	sch.[cclregs_accountidName],
	sch.[cclregs_licensetype],
	sch.[cclregs_regulatedschemeid],
	sch.[ricsv1_sponsorshipvouchercode],
	sch.[cclregs_susstartdate],
	sch.[cclregs_suspensionremovedbyidName],
	sch.[cclregs_suspensioninvokedbyidName],
	sch.[cclregs_susenddate],
	sch.[cclregs_sustext],
	sch.[StatusCode_Description],
	sch.[StateCode_Description],
	sch.[cclregs_sponsoringfirmidName],
	sch.[ricsv1_servicestopublic_Description],
	sch.[ricsv1_selfdeclaredvrseligible_Description],
	sch.[rics_schemelicencestatus_Description],
	sch.[cclregs_ceasedreason],
	sm.[Value] as [cclregs_ceasedreason_description],
	sch.[cclregs_ceaseddate],
	sch.[cclregs_licenseapprovaldate],
	sch.[cclregs_regulatoryroleidName],
	sch.[cclregs_regulatorycontactofficerid],
	sch.[ricsv1_regulatedentityname],
	sch.[cclevent_regulatedareaidName],
	sch.[cclregs_submissiondate],
	sch.[cclregs_inclusionreason_Description],
	sch.[ricsv1_ParentSchemeName],
	sch.[OwnerIdName],
	sch.[ricsv1_organisationtype_Description],
	sch.[ricsv1_directorprincipals],
	sch.[cclregs_sponsoredmembernum],
	sch.[cclregs_sponsored_Description],
	sch.[cclregs_memberschemestatus],
	sch.[ricsv1_memberdirectorprincipals],
	sch.[rics_licenceconditionsexpirydate],
	sch.[rics_legacylicencenumber],
	sch.[ricsv1_isrobustregistration],
	sch.[ricsv1_holdsclientmoney_Description],
	sch.[ricsv1_haspii_Descriotion],
	sch.[ricsv1_gima_Description],
	sch.[cclregs_firmschemestatus_Description],
	sch.[ricsv1_dayssincelastmodified],
	sch.[ricsv1_datesignedoff],
	sch.[cclregs_availabilitydate],
	sch.[rics_laststatuschangedate],
	sch.[cclregs_contactwhosubmittedtheregistratidName],
	sch.[ricsv1_clientmoneytype_Description],
	sch.[rics_approvalconditions],
	sch.[rics_officenumber],
	sch.[ricsv1_isregulatedoffice],
	sch.[rics_isheadoffice],
	sch.[rics_firmnumber],
	sch.[rics_contactno],
	sch.[cclregs_contactid],
	sch.[Seconday_SchemeName],
	sch.[Secondary_Contactno]
FROM [Ext].[PBI02_RegsBI_vwSchemes] sch
	LEFT JOIN dbo.vwStringmap sm
		ON sch.cclregs_ceasedreason = sm.[AttributeValue]
		AND sm.AttributeName = 'cclregs_ceasedreason'
		AND sm.ObjectTypeCode = 10127
